function event_spawn(e)
	eq.set_timer("first_cast",1000);
	eq.set_timer("cast_spell",10*1000);
end

function event_timer(e)
	if e.timer=="cast_spell" then
		e.self:CastSpell(4795, e.self:GetID()); --Aura of Restoration
	elseif e.timer=="first_cast" then
		e.self:CastSpell(4795, e.self:GetID()); --Aura of Restoration
		eq.stop_timer("first_cast");
	end
end

function event_signal(e)
	if(e.signal == 1) then
		e.self:Say("The boss might need some help!");
		local stanos = eq.get_entity_list():GetMobByNpcTypeID(5088); -- Stanos_Herkanor
		if ( stanos.valid ) then
			e.self:MoveTo(stanos:GetX(), stanos:GetY(), stanos:GetZ(), -1, false);
		end
	end
end

function event_combat(e)
	if(e.joined) then
		random_say = math.random(100);
		if(random_say <= 30) then
			e.self:Say("Death!!  Death to all who oppose the Crushbone orcs!!");
		elseif(random_say <= 65) then
			e.self:Say("Hail, Emperor Crush!!");
		else
			e.self:Say("Fall before the might of Clan Crushbone!!");
		end
	end
end

--a_suspended_commoner
--potimea

function event_say(e)
	if(e.message:findi("hail") and not e.self:IsEngaged()) then
		if e.self:GetX() == 606 and e.self:GetY() == 104 then	
			e.self:Say("Who are you and what are your intentions here " .. e.other:GetName() .. "! This is a realm that is beyond any that you have ever seen before. Tread lightly for danger could possibly lie behind every corner.");
		elseif e.self:GetX() == 1020 and e.self:GetY() == 195 then
			e.self:Say("Greetings, stranger! I have been here for as long as I can remember. It's a lot like home though you know nice and cool which is just how I like it.");
		elseif e.self:GetX() == 1066 and e.self:GetY() == 105 then	
			e.self:Say("I am pleased to meet a newcomer to this realm, do you by chance know why you have been placed here. I certainly do not and hope to find out what has become of me someday.");
		elseif e.self:GetX() == 502 and e.self:GetY() == -589 then	
			e.self:Say("Cold it sure is in these parts " .. e.other:GetName() .. ". But lucky for me I am very used to my surroundings. I do not know why I was placed here and I have no idea how to return to my normal existence.");
		elseif e.self:GetX() == 626 and e.self:GetY() == -699 then	
			e.self:Say("A new face, not something I see often. I have seen the same folks here for all of my days, including the day I was first banished. It is very odd because I still do not remember much of my separation from the mortal world.");
		elseif e.self:GetX() == 756 and e.self:GetY() == -591 then	
			e.self:Say("It's very nice to see a new visitor to this land, I have not seen anyone else besides my companions here for a very long time. Although I was placed here involuntarily I am sure it would be very difficult to arrive here purposely.");
		end
	end
end

function event_combat(e)
if e.joined then
e.self:Emote("not quite sure what a moldmaster is, but you are sure that you don't want to meet it alone, and in the dark.");
eq.depop_with_timer();
end
end

function event_say(e)
	if e.message:findi("hail") then
		e.self:Say("The ritual of destruction has begun. Tiv Barxt Qurat has completed the transfer of destructive energy from the Altar of Destruction into the Guardian of Destruction and it must be destroyed if there is any chance of disrupting his plans. Be wary of Barxt -- he is powerful and tricky. If he sees things are not going his way, he will use many different tactics to destroy you. When you are [ready] to enter, tell me so, and I will remove the seal. However, once you enter, I am afraid the only way out will be through death or victory.");
	elseif e.message:findi("ready") then
		e.self:Say("The seal has been removed. Good luck to you.");
		eq.get_entity_list():FindDoor(5):SetLockPick(0);
		eq.zone_emote(MT.Yellow,"Within the large chamber lies a massive stone guardian and many trusik. As they wave their arms and chant, you hear a raspy voice near the large altar in the center of the room. You have disrupted the ritual of destruction. Your interference is an annoyance to the great Trushar and it is his will that you be dealt with. Defilers, witness what happens when the destructive forces of Trushar are combined with my geomantic knowledge. Rise, Guardian of Destruction! Come to life and destroy those who would defile this temple!");
		eq.zone_emote(MT.Yellow,"I can feel the energy from the guardian course through my soul! More! Give me more, I say! Trushar, give me the power to destroy these creatures and send them and the others back from where they came!");
	end
end

function event_signal(e)
	entity_list = eq.get_entity_list();

	if(e.signal == 1) then
		e.self:Say("Such is the will of Cazic-Thule!");
	elseif(e.signal == 2) then
		local mobtypeID =  entity_list:GetMobByNpcTypeID(72003);
		local follow_mob = mobtypeID:GetID();
		eq.follow(follow_mob);
	elseif(e.signal == 3) then
		eq.stop_follow();
	end
end

function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Hello. stranger. I would talk to thee. but [Barn] has instructed me not to converse with strangers.");
	elseif(e.message:findi("Barn")) then
		e.self:Say("Barn is my hero. He saved me from a life on the evil streets in Freeport.");
	end
end

function event_say(e)
    e.self:Say("Where's me ale?!  I cannot sail without me ale!  Hey that rhymed methinks!'  Konamel begins to sing an old sea chantey.");
end

function event_trade(e)
	local item_lib = require("items");
	item_lib.return_items(e.self, e.other, e.trade);
end

function event_spawn(e)
eq.set_timer('depop', 900 * 1000);
end

function event_combat(e)
if e.joined then
if(not eq.is_paused_timer('depop')) then
			eq.pause_timer('depop');
		end
	else
		eq.resume_timer('depop');
		e.self:SaveGuardSpot(e.self:GetX(),e.self:GetY(), e.self:GetZ(), e.self:GetHeading());
	end
end

function event_timer(e)
if (e.timer == 'depop') then
eq.depop();
end
end

function event_combat(e)
	if e.joined then
		eq.set_timer("rain", math.random(3,60) * 1000);
		eq.set_timer("breath", math.random(3,45) * 1000);
		eq.set_timer("pres", math.random(3,30) * 1000);
	else
		eq.stop_timer("rain");
		eq.stop_timer("breath");
		eq.stop_timer("pres");
	end
end

function event_timer(e)
	if e.timer=="rain" then
		e.self:CastSpell(3764, e.self:GetTarget():GetID()); -- Spell: Rain of Bile
		eq.set_timer("rain", 60 * 1000);
	elseif e.timer=="breath" then
		e.self:CastSpell(6112, e.self:GetTarget():GetID()); -- Spell: Fetid Breath
		eq.set_timer("breath", 60 * 1000);	
	elseif e.timer=="pres" then
		e.self:CastSpell(6113, e.self:GetTarget():GetID()); -- Spell: Disconcerting Presence
		eq.set_timer("pres", 120 * 1000);	
	end
end

function event_spawn(e)
	e.self:SetRunning(true);
end

function event_signal(e)
	if(e.signal == 1) then
		eq.stop();
		e.self:MerchantCloseShop();
	elseif(e.signal == 2) then
		eq.start(60);
		e.self:MerchantOpenShop();
	end
end

function event_say(e)
	if(e.message:findi("hail")) then
		e.self:Say("Greetings!!  Moran here.  I just love this city.  I traveled from Freeport to Qeynos to stay far from the [Freeport Militia].");
	elseif(e.message:findi("freeport militia")) then
		e.self:Say("The Freeport Militia are nothing more than thugs.  I have seen them lay waste to more than a dozen adventurers at once.  For no reason other than to flex their muscles!");
	end
end

