function BossChange(mob_id,targetable_id,num)
	old_boss = eq.get_entity_list():GetMobByNpcTypeID(mob_id);
	boss = eq.unique_spawn(targetable_id,0,0,old_boss:GetX(),old_boss:GetY(),old_boss:GetZ(),385);
